def parse(alert):
    host_name = alert.get('host', {}).get('name')
    # In a production context, map hostname to VMID (e.g. windows-target -> 201)
    vmid_map = {'windows-target': '201', 'linux-target': '200'}
    return {
        'vmid': vmid_map.get(host_name, 'unknown'),
        'node': 'pve',
        'severity': alert.get('kibana.alert.severity')
    }
